// Optional owner-only table checker; not run automatically in public CI.
// It reads a private TSV generated by verify_dynamic_difficulty_gpv.py.
#include "sin_compat/dynamic_difficulty_gpv.hpp"
#include <cmath>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace sin_compat;
int main(int argc,char**argv) {
    if(argc!=2) {
        std::cerr<<"usage: sin_dynamic_difficulty_private_audit /private/original-gpv.tsv\n";
        return 2;
    }
    std::ifstream in(argv[1]);
    if(!in)return 3;
    std::string line;
    if(!std::getline(in,line) ||
       line!="name\tcurrent\tlow_target\thigh_target\trating_low\trating_high")
        return 4;
    std::vector<GameplayVariableDefinition> rows;
    std::vector<std::string> names;
    while(std::getline(in,line)) {
        if(line.empty())continue;
        std::istringstream fields(line);
        std::string cell;
        std::vector<std::string> cols;
        while(std::getline(fields,cell,'\t'))cols.push_back(cell);
        if(cols.size()!=6)return 5;
        try {
            GameplayVariableDefinition d;
            d.name=cols[0];
            d.current=std::stof(cols[1]);
            d.low_target=std::stof(cols[2]);
            d.high_target=std::stof(cols[3]);
            d.rating_low=std::stof(cols[4]);
            d.rating_high=std::stof(cols[5]);
            rows.push_back(d); names.push_back(d.name);
        } catch(const std::exception&) {return 5;}
    }
    if(rows.size()!=14)return 6;
    GameplayDifficultyVariables model;
    std::string error;
    if(!model.configure(rows,&error)) {
        std::cerr<<"invalid private GPV table: "<<error<<'\n';return 7;
    }
    const auto before=model.current_challenge(names);
    if(!before || before.recognized_entries!=14)return 8;
    if(model.interpolate(0.5f)!=GameplayDifficultyStatus::Ok)return 9;
    const auto mid=model.current_challenge(names);
    if(!mid || std::fabs(before.rating_percent-mid.rating_percent)>0.0001f)return 10;
    if(model.interpolate(0)!=GameplayDifficultyStatus::Ok ||
       model.interpolate(1)!=GameplayDifficultyStatus::Ok)return 11;
    std::cout<<"private: 14 GPV entries verified; all-14-selected modeled rating "
             <<before.rating_percent<<" (NOT a verified live game rating)\n";
    return 0;
}
